const generatedSwiftHeader =
    '// GENERATED by native_ai_bridge_generator. Do not edit.';

const generatedSkillHeader =
    '<!-- GENERATED by native_ai_bridge_generator. Do not edit. -->';

const swiftFileSuffix = '.g.swift';
const skillFileName = 'SKILL.md';

String swiftFileName(String typeName) => '$typeName$swiftFileSuffix';

String skillFilePath(String skillName) => '$skillName/$skillFileName';

String normalizeSkillBody(String body) {
  final trimmed = body
      .replaceAll('\r\n', '\n')
      .replaceFirst(RegExp(r'^\n+'), '')
      .trimRight();
  return '$trimmed\n';
}
